 },
 "milestones": [
  {
   "id": "M1",
   "target": "One invoice record for vendor Rao Packaging Industries exists with invoice number INV-2210, po number PO-2026-0431, amount 1850000 paise, tax 282203 paise, invoice date 2026-10-04, due date 2026-11-03",
   "sop_step": "PI-5",
   "checked_by": [
    {
     "read": "list_invoices",
     "args": {
      "vendor": 2
     },
     "where": {
      "invoice_no": "INV-2210"
     },
     "expect": {
      "amount_paise": 1850000,
      "due_date": "2026-11-03",
      "invoice_date": "2026-10-04",
      "invoice_no": "INV-2210",
      "po_number": "PO-2026-0431",
      "tax_paise": 282203,
      "vendor_id": 2,
      "vendor_name": "Rao Packaging Industries"
