   "target": "The invoice record shows the source PDF rao_INV-2210.pdf as its attached file.",
   "sop_step": "PI-6",
   "checked_by": [
    {
     "read": "get_invoice",
     "args": {
      "invoice_id": {
       "ref": "M1"
      }
     },
     "where": {
      "id": {
       "ref": "M1"
      }
     },
     "expect": {
      "source_file": "rao_INV-2210.pdf"
     }
    }
   ]
  },
  {
   "id": "M3",
